render:
const svg = ctx.root.querySelector('svg');
if (!svg) return;

const t = ctx.time;
const p = ctx.params;

// 1. GESTIÓN DEL FONDO (SÓLIDO VS GRADIENTE)
const bgRect = svg.querySelector('#bg-rect');
if (p.bg_type === 'solid') {
  bgRect.setAttribute('fill', p.bg_solid_color || '#00FF00');
} else {
  bgRect.setAttribute('fill', 'url(#sky)');
  svg.querySelector('#sky-stop-1').setAttribute('stop-color', p.sky_top_color || '#9fe0ec');
  svg.querySelector('#sky-stop-2').setAttribute('stop-color', p.sky_bottom_color || '#f9e7b7');
}

// 2. CONFIGURACIÓN DE NUBES Y MONTAÑAS
const clouds = svg.querySelector('#clouds');
clouds.style.display = p.show_clouds ? 'block' : 'none';
if (p.show_clouds) {
  clouds.setAttribute('transform', `translate(${Math.sin(t * 0.35) * 20} 0)`);
}

svg.querySelector('#m-path-1').setAttribute('fill', p.mountain_color_1 || '#b5c89b');
svg.querySelector('#m-path-2').setAttribute('fill', p.mountain_color_2 || '#79a967');
svg.querySelector('#m-path-3').setAttribute('fill', p.mountain_color_3 || '#528b61');

// 3. COLORES DEL DRON Y DETALLES
svg.querySelector('#shell-stop-1').setAttribute('stop-color', p.drone_shell_top || '#fff2ba');
svg.querySelector('#shell-stop-2').setAttribute('stop-color', p.drone_shell_bottom || '#f3bb56');
svg.querySelector('#shell-base').setAttribute('fill', p.drone_shell_bottom || '#f3bb56');
svg.querySelector('#eye-ring').setAttribute('stroke', p.drone_accent_color || '#e3a549');
svg.querySelector('#leg-accent').setAttribute('stroke', p.drone_accent_color || '#e3a549');
svg.querySelector('#eye').setAttribute('fill', p.eye_color || '#31a8bd');

svg.querySelectorAll('.rotor-cap').forEach(cap => {
  cap.setAttribute('fill', p.drone_shell_top || '#fff2ba');
});

// 4. ANIMACIÓN Y FÍSICA DEL DRON
const motionMult = p.motion !== undefined ? p.motion : 1;
const hoverSpeedMult = p.hover_speed !== undefined ? p.hover_speed : 1;
const rotorSpeedMult = p.rotor_speed !== undefined ? p.rotor_speed : 1;
const droneScale = p.drone_scale !== undefined ? p.drone_scale : 1.0;

const drone = svg.querySelector('#drone');
const appear = Math.min(1, Math.max(0, (t - 0.32) / 1.18));
const smooth = x => x * x * (3 - 2 * x);
const lift = 1 - smooth(appear);

const bob = Math.sin(t * 4.6 * hoverSpeedMult) * 11 * motionMult;
const drift = Math.sin(t * 1.1 * hoverSpeedMult) * 24 * motionMult;
const rise = lift * 480;
const roll = Math.sin(t * 2.25 * hoverSpeedMult) * 2.2 * motionMult;

drone.setAttribute('transform', `translate(${drift} ${-rise + bob}) rotate(${roll} 540 550) scale(${droneScale})`);

// 5. SOMBRA EN EL SUELO
const shadow = svg.querySelector('#shadow');
if (p.show_shadow) {
  shadow.style.display = 'block';
  shadow.setAttribute('opacity', String(Math.max(0.1, 1 - lift * 0.9)));
} else {
  shadow.style.display = 'none';
}

// 6. ROTACIÓN DE HÉLICES Y PARPADEO
for (let i = 0; i < 4; i++) {
  const el = svg.querySelectorAll('.rotor')[i];
  const x = [217, 863, 182, 898][i];
  const y = [430, 430, 519, 519][i];
  const stretch = 0.52 + 0.48 * Math.abs(Math.sin((t * 34 * rotorSpeedMult) + i * 1.7));
  el.setAttribute('transform', `translate(${x} ${y}) scale(${stretch} 1)`);
}

const eye = svg.querySelector('#eye');
const blink = Math.max(0, 1 - Math.abs((t % 3.7) - 2.55) / 0.12);
eye.setAttribute('ry', String(37 * (1 - blink * 0.93)));
